namespace InformationWeb.Controls.Dorm.DormRegister
{
    public static class DormRegisterConst
    {
        public const byte StatusPending = 1;
        public const byte StatusApproved = 2;
        public const byte StatusRejected = 3;
        public const byte StatusCancelled = 4;

        public const int BedStatusEmpty = 0;
        public const int BedStatusHeld = 1;
        public const int BedStatusOccupied = 2;

        public const string PERMISSION_APPROVE = "SIM_RegisterDorm_Edit";
        public const string PERMISSION_VIEW = "SIM_RegisterDorm_View";
    }
}

using System;
using System.Data;
using SimsObject;

namespace InformationWeb.Controls.Dorm.DormRegister
{
    public class DormRegisterDataAccess
    {
        private SIM_DormBed objData = new SIM_DormBed();

        public Exception ErrorException
        {
            get { return objData.ErrorException; }
        }

        public DataSet GetStudentContext(long studentId)
        {
            DataTable dtbSummary = objData.GetDataTable("WEB_Dorm_Register_GetStudentContext", "@StudentID", studentId);
            if (dtbSummary == null)
            {
                return null;
            }

            DataSet ds = new DataSet();
            ds.Tables.Add(dtbSummary.Copy());
            if (dtbSummary.Rows.Count > 0)
            {
                object objRequestId = dtbSummary.Rows[0]["RegisterRequestID"];
                if (objRequestId != null && objRequestId != DBNull.Value)
                {
                    long lngRequestId = Convert.ToInt64(objRequestId);
                    if (lngRequestId > 0)
                    {
                        DataTable dtbPending = objData.GetDataTable(
                            "WEB_Dorm_Register_GetDetail",
                            "@RegisterRequestID", lngRequestId);
                        if (dtbPending != null)
                        {
                            dtbPending.TableName = "PendingDetail";
                            ds.Tables.Add(dtbPending.Copy());
                        }
                    }
                }
            }
            return ds;
        }

        public DataTable GetDormListForRegister(string areaId, long studentId)
        {
            return objData.GetDataTable(
                "WEB_Dorm_Dorm_ListForRegister",
                "@AreaID", string.IsNullOrEmpty(areaId) ? null : areaId,
                "@StudentID", studentId);
        }

        public DataTable GetBedListForRegister(string dormId, long studentId)
        {
            return objData.GetDataTable(
                "WEB_Dorm_Bed_ListForRegister",
                "@DormID", dormId,
                "@StudentID", studentId);
        }

        public DataTable GetPendingList()
        {
            return objData.GetDataTable("WEB_Dorm_Register_SearchPending");
        }

        public DataTable GetRequestDetail(long registerRequestId)
        {
            return objData.GetDataTable(
                "WEB_Dorm_Register_GetDetail",
                "@RegisterRequestID", registerRequestId);
        }

        public long? SubmitRegister(long studentId, string dormBedId, string createdUser)
        {
            DataTable dtb = objData.GetDataTable(
                "WEB_Dorm_Register_Submit",
                "@StudentID", studentId,
                "@DormBedID", dormBedId,
                "@CreatedUser", createdUser);
            return ReadRegisterRequestId(dtb);
        }

        public long? ChangeBed(long studentId, long registerRequestId, string dormBedId, string updatedUser)
        {
            DataTable dtb = objData.GetDataTable(
                "WEB_Dorm_Register_ChangeBed",
                "@StudentID", studentId,
                "@RegisterRequestID", registerRequestId,
                "@DormBedID", dormBedId,
                "@UpdatedUser", updatedUser);
            return ReadRegisterRequestId(dtb);
        }

        public bool CancelRegister(long studentId, long registerRequestId)
        {
            return objData.ExecNonQuery(
                "WEB_Dorm_Register_Cancel",
                "@StudentID", studentId,
                "@RegisterRequestID", registerRequestId);
        }

        public bool Approve(long registerRequestId, string processUser)
        {
            return objData.ExecNonQuery(
                "WEB_Dorm_Register_Approve",
                "@RegisterRequestID", registerRequestId,
                "@ProcessUser", processUser);
        }

        public bool Reject(long registerRequestId, string rejectReason, string processUser)
        {
            return objData.ExecNonQuery(
                "WEB_Dorm_Register_Reject",
                "@RegisterRequestID", registerRequestId,
                "@RejectReason", rejectReason,
                "@ProcessUser", processUser);
        }

        private static long? ReadRegisterRequestId(DataTable dtb)
        {
            if (dtb == null || dtb.Rows.Count == 0)
            {
                return null;
            }
            if (dtb.Columns.Contains("RegisterRequestID"))
            {
                return Convert.ToInt64(dtb.Rows[0]["RegisterRequestID"]);
            }
            return null;
        }
    }
}

using System;
using System.Data;
using System.Globalization;
using System.Web.UI;
using System.Web.UI.WebControls;
using DCore;
using SimsObject;
using WebGlobal;

namespace InformationWeb.Controls.Dorm.DormRegister
{
    public partial class StudentRegister : ControlBase
    {
        private DormRegisterDataAccess dataAccess = new DormRegisterDataAccess();

        protected void Page_Load(object sender, EventArgs e)
        {
            if (Session[Globals.USER] == null)
            {
                MsgBox.ShowError("Bạn chưa đăng nhập hệ thống!");
                return;
            }

            if (WebGlobal.StudentID <= 0)
            {
                MsgBox.ShowError("Chức năng dành cho sinh viên đăng nhập.");
                return;
            }

            if (!IsPostBack)
            {
                LoadStudentState();
            }
        }

        protected void ddlArea_SelectedIndexChanged(object sender, EventArgs e)
        {
            LoadDormDropdown();
            ClearBedList();
            udpMain.Update();
        }

        protected void ddlDorm_SelectedIndexChanged(object sender, EventArgs e)
        {
            LoadBedList();
            udpMain.Update();
        }

        protected void btnChangeBed_Click(object sender, EventArgs e)
        {
            hidIsChangeMode.Value = "1";
            litWizardTitle.Text = "Đổi giường / phòng";
            btnWizardCancel.Visible = true;
            pnlWizard.Visible = true;
            LoadAreaDropdown();
            ClearBedList();
            udpMain.Update();
        }

        protected void btnWizardCancel_Click(object sender, EventArgs e)
        {
            hidIsChangeMode.Value = "0";
            pnlWizard.Visible = false;
            LoadStudentState();
        }

        protected void btnCancelRequest_Click(object sender, EventArgs e)
        {
            long lngRequestId;
            if (!long.TryParse(hidRegisterRequestID.Value, out lngRequestId) || lngRequestId <= 0)
            {
                MsgBox.ShowWarning("Không xác định được đơn đăng ký.");
                return;
            }

            if (!dataAccess.CancelRegister(WebGlobal.StudentID, lngRequestId))
            {
                string strErr = dataAccess.ErrorException != null ? dataAccess.ErrorException.Message : "Hủy đăng ký thất bại.";
                MsgBox.ShowError(strErr);
                return;
            }

            MsgBox.ShowInfo("Đã hủy đăng ký ký túc xá.");
            LoadStudentState();
        }

        protected void btnConfirm_Click(object sender, EventArgs e)
        {
            if (string.IsNullOrEmpty(rblBed.SelectedValue))
            {
                MsgBox.ShowWarning("Vui lòng chọn giường còn trống.");
                return;
            }

            string strUser = User != null ? User.UserName : "web";
            string strBedId = rblBed.SelectedValue;
            bool bolChange = hidIsChangeMode.Value == "1";

            if (bolChange)
            {
                long lngRequestId;
                if (!long.TryParse(hidRegisterRequestID.Value, out lngRequestId) || lngRequestId <= 0)
                {
                    MsgBox.ShowWarning("Không xác định được đơn đăng ký.");
                    return;
                }

                long? lngResult = dataAccess.ChangeBed(WebGlobal.StudentID, lngRequestId, strBedId, strUser);
                if (lngResult == null)
                {
                    string strErr = dataAccess.ErrorException != null ? dataAccess.ErrorException.Message : "Đổi giường thất bại.";
                    MsgBox.ShowError(strErr);
                    return;
                }

                MsgBox.ShowInfo("Đã cập nhật giường đăng ký. Trạng thái vẫn là chờ duyệt.");
            }
            else
            {
                long? lngResult = dataAccess.SubmitRegister(WebGlobal.StudentID, strBedId, strUser);
                if (lngResult == null)
                {
                    string strErr = dataAccess.ErrorException != null ? dataAccess.ErrorException.Message : "Đăng ký thất bại.";
                    MsgBox.ShowError(strErr);
                    return;
                }

                MsgBox.ShowInfo("Đã gửi đăng ký. Vui lòng chờ quản lý duyệt.");
            }

            hidIsChangeMode.Value = "0";
            pnlWizard.Visible = false;
            LoadStudentState();
        }

        private void LoadStudentState()
        {
            pnlAlreadyInDorm.Visible = false;
            pnlPending.Visible = false;
            pnlWizard.Visible = false;
            btnWizardCancel.Visible = false;
            hidIsChangeMode.Value = "0";

            DataSet ds = dataAccess.GetStudentContext(WebGlobal.StudentID);
            if (ds == null || ds.Tables.Count == 0 || ds.Tables[0].Rows.Count == 0)
            {
                MsgBox.ShowError("Không tải được trạng thái đăng ký.");
                return;
            }

            DataRow drw = ds.Tables[0].Rows[0];
            bool bolActive = Convert.ToBoolean(drw["HasActiveRegister"]);
            bool bolPending = Convert.ToBoolean(drw["HasPendingRequest"]);

            if (bolActive)
            {
                pnlAlreadyInDorm.Visible = true;
                return;
            }

            if (bolPending)
            {
                DataTable dtbDetail = null;
                if (ds.Tables.Count > 1)
                {
                    dtbDetail = ds.Tables[1];
                }
                if (dtbDetail == null || dtbDetail.Rows.Count == 0)
                {
                    long lngId = Convert.ToInt64(drw["RegisterRequestID"]);
                    dtbDetail = dataAccess.GetRequestDetail(lngId);
                }

                if (dtbDetail != null && dtbDetail.Rows.Count > 0)
                {
                    BindPendingPanel(dtbDetail.Rows[0]);
                }
                pnlPending.Visible = true;
                return;
            }

            litWizardTitle.Text = "Chọn khu — phòng — giường";
            pnlWizard.Visible = true;
            LoadAreaDropdown();
            ClearBedList();
        }

        private void BindPendingPanel(DataRow drw)
        {
            hidRegisterRequestID.Value = drw["RegisterRequestID"].ToString();
            litPendingArea.Text = drw["AreaName"].ToString();
            litPendingDorm.Text = drw["DormName"].ToString();
            litPendingBed.Text = drw["DormBedName"].ToString();
            litPendingDate.Text = FormatDate(drw["RegisterDate"]);
        }

        private void LoadAreaDropdown()
        {
            SIM_Area obj = new SIM_Area();
            DataTable dtb = obj.GetAll();
            DormWebLookup.BindTable(ddlArea, dtb, SIM_Area.C_AreaID, SIM_Area.C_AreaName);
        }

        private void LoadDormDropdown()
        {
            ddlDorm.Items.Clear();
            ddlDorm.Items.Add(new ListItem("-- Chọn --", ""));

            if (string.IsNullOrEmpty(ddlArea.SelectedValue))
            {
                return;
            }

            DataTable dtb = dataAccess.GetDormListForRegister(ddlArea.SelectedValue, WebGlobal.StudentID);
            if (dtb == null)
            {
                MsgBox.ShowError("Không tải được danh sách phòng.");
                return;
            }

            DormWebLookup.BindTable(ddlDorm, dtb, SIM_Dorm.C_DormID, SIM_Dorm.C_DormName);
        }

        private void LoadBedList()
        {
            rblBed.Items.Clear();
            pnlBedList.Visible = false;

            if (string.IsNullOrEmpty(ddlDorm.SelectedValue))
            {
                lblBedHint.Text = "Chọn phòng để xem danh sách giường.";
                return;
            }

            DataTable dtb = dataAccess.GetBedListForRegister(ddlDorm.SelectedValue, WebGlobal.StudentID);
            if (dtb == null)
            {
                MsgBox.ShowError("Không tải được danh sách giường.");
                return;
            }

            int intSelectable = 0;
            foreach (DataRow drw in dtb.Rows)
            {
                int intStatus = Convert.ToInt32(drw["BedStatus"]);
                string strName = drw["DormBedName"].ToString();
                string strLabel;
                if (intStatus == DormRegisterConst.BedStatusOccupied)
                {
                    strLabel = string.Format("{0} — Đã có người", strName);
                }
                else if (intStatus == DormRegisterConst.BedStatusHeld)
                {
                    if (Convert.ToInt32(drw["IsMyPendingBed"]) == 1)
                    {
                        strLabel = string.Format("{0} — Giữ chỗ (của bạn)", strName);
                    }
                    else
                    {
                        strLabel = string.Format("{0} — Giữ chỗ", strName);
                    }
                }
                else
                {
                    strLabel = string.Format("{0} — Trống", strName);
                }

                ListItem item = new ListItem(strLabel, drw["DormBedID"].ToString());
                item.Enabled = Convert.ToInt32(drw["IsSelectable"]) == 1;
                rblBed.Items.Add(item);
                if (item.Enabled)
                {
                    intSelectable++;
                }
            }

            pnlBedList.Visible = dtb.Rows.Count > 0;
            lblBedHint.Text = intSelectable > 0
                ? "Chọn một giường còn trống."
                : "Phòng này không còn giường trống.";
        }

        private void ClearBedList()
        {
            rblBed.Items.Clear();
            pnlBedList.Visible = false;
            lblBedHint.Text = "Chọn phòng để xem danh sách giường.";
        }

        private static string FormatDate(object value)
        {
            if (value == null || value == DBNull.Value)
            {
                return string.Empty;
            }

            DateTime dtm;
            if (value is DateTime)
            {
                dtm = (DateTime)value;
            }
            else if (!DateTime.TryParse(value.ToString(), out dtm))
            {
                return string.Empty;
            }

            return dtm.ToString("dd/MM/yyyy", CultureInfo.InvariantCulture);
        }
    }
}

