using System;
using System.Data;
using System.Globalization;
using System.Web.UI.WebControls;
using DCore;
using WebGlobal;

namespace InformationWeb.Controls.Dorm.DormRegister
{
    public partial class Approve : ControlBase
    {
        private DormRegisterDataAccess dataAccess = new DormRegisterDataAccess();

        protected void Page_Load(object sender, EventArgs e)
        {
            if (Session[Globals.USER] == null)
            {
                MsgBox.ShowError("Bạn chưa đăng nhập hệ thống!");
                return;
            }

            if (!WebGlobal.HasPermission(DormRegisterConst.PERMISSION_APPROVE)
                && !WebGlobal.HasPermission(DormRegisterConst.PERMISSION_VIEW))
            {
                MsgBox.ShowError("Bạn không có quyền duyệt đăng ký ký túc xá.");
                return;
            }

            if (!IsPostBack)
            {
                LoadPendingGrid();
            }
        }

        protected void grdPending_SelectedIndexChanged(object sender, EventArgs e)
        {
            if (grdPending.SelectedDataKey == null)
            {
                return;
            }

            long lngId = Convert.ToInt64(grdPending.SelectedDataKey.Value);
            hidSelectedRequestID.Value = lngId.ToString();
            LoadDetail(lngId);
            udpAll.Update();
        }

        protected void grdPending_RowDataBound(object sender, GridViewRowEventArgs e)
        {
            if (e.Row.RowType != DataControlRowType.DataRow)
            {
                return;
            }

            if (e.Row.Cells.Count > 7)
            {
                object objDate = DataBinder.Eval(e.Row.DataItem, "RegisterDate");
                if (objDate != null && objDate != DBNull.Value)
                {
                    DateTime dtm = Convert.ToDateTime(objDate);
                    e.Row.Cells[7].Text = dtm.ToString("dd/MM/yyyy", CultureInfo.InvariantCulture);
                }
            }
        }

        protected void btnApprove_Click(object sender, EventArgs e)
        {
            if (!WebGlobal.HasPermission(DormRegisterConst.PERMISSION_APPROVE))
            {
                MsgBox.ShowWarning("Bạn không có quyền duyệt.");
                return;
            }

            long lngId;
            if (!long.TryParse(hidSelectedRequestID.Value, out lngId) || lngId <= 0)
            {
                MsgBox.ShowWarning("Vui lòng chọn một đơn trong danh sách.");
                return;
            }

            string strUser = User != null ? User.UserName : "web";
            if (!dataAccess.Approve(lngId, strUser))
            {
                string strErr = dataAccess.ErrorException != null ? dataAccess.ErrorException.Message : "Duyệt thất bại.";
                MsgBox.ShowError(strErr);
                return;
            }

            MsgBox.ShowInfo("Đã duyệt đăng ký và ghi nhận nội trú.");
            pnlDetail.Visible = false;
            hidSelectedRequestID.Value = string.Empty;
            txtRejectReason.Text = string.Empty;
            LoadPendingGrid();
        }

        protected void btnReject_Click(object sender, EventArgs e)
        {
            if (!WebGlobal.HasPermission(DormRegisterConst.PERMISSION_APPROVE))
            {
                MsgBox.ShowWarning("Bạn không có quyền từ chối.");
                return;
            }

            long lngId;
            if (!long.TryParse(hidSelectedRequestID.Value, out lngId) || lngId <= 0)
            {
                MsgBox.ShowWarning("Vui lòng chọn một đơn trong danh sách.");
                return;
            }

            if (string.IsNullOrWhiteSpace(txtRejectReason.Text))
            {
                MsgBox.ShowWarning("Vui lòng nhập lý do từ chối.");
                return;
            }

            string strUser = User != null ? User.UserName : "web";
            if (!dataAccess.Reject(lngId, txtRejectReason.Text.Trim(), strUser))
            {
                string strErr = dataAccess.ErrorException != null ? dataAccess.ErrorException.Message : "Từ chối thất bại.";
                MsgBox.ShowError(strErr);
                return;
            }

            MsgBox.ShowInfo("Đã từ chối đăng ký.");
            pnlDetail.Visible = false;
            hidSelectedRequestID.Value = string.Empty;
            txtRejectReason.Text = string.Empty;
            LoadPendingGrid();
        }

        private void LoadPendingGrid()
        {
            DataTable dtb = dataAccess.GetPendingList();
            if (dtb == null)
            {
                MsgBox.ShowError("Không tải được danh sách chờ duyệt.");
                return;
            }

            grdPending.DataSource = dtb;
            grdPending.DataBind();
        }

        private void LoadDetail(long registerRequestId)
        {
            DataTable dtb = dataAccess.GetRequestDetail(registerRequestId);
            if (dtb == null || dtb.Rows.Count == 0)
            {
                MsgBox.ShowWarning("Không tìm thấy chi tiết đơn.");
                pnlDetail.Visible = false;
                return;
            }

            DataRow drw = dtb.Rows[0];
            litFullname.Text = drw["Fullname"].ToString();
            litStudentCode.Text = drw["StudentCode"].ToString();
            litArea.Text = drw["AreaName"].ToString();
            litDorm.Text = drw["DormName"].ToString();
            litBed.Text = drw["DormBedName"].ToString();
            litRegisterDate.Text = FormatDate(drw["RegisterDate"]);
            txtRejectReason.Text = string.Empty;
            pnlDetail.Visible = true;
        }

        private static string FormatDate(object value)
        {
            if (value == null || value == DBNull.Value)
            {
                return string.Empty;
            }

            DateTime dtm = Convert.ToDateTime(value);
            return dtm.ToString("dd/MM/yyyy", CultureInfo.InvariantCulture);
        }
    }
}

