protected void rptBed_ItemDataBound(object sender, RepeaterItemEventArgs e)
{
    if (e.Item.ItemType != ListItemType.Item && e.Item.ItemType != ListItemType.AlternatingItem)
    {
        return;
    }

    DataRowView drv = e.Item.DataItem as DataRowView;
    if (drv == null)
    {
        return;
    }

    int intStatus = Convert.ToInt32(drv["BedStatus"]);
    bool bolSelectable = Convert.ToInt32(drv["IsSelectable"]) == 1;
    bool bolMine = Convert.ToInt32(drv["IsMyPendingBed"]) == 1;

    Panel pnlCard = e.Item.FindControl("pnlBedCard") as Panel;
    RadioButton rdo = e.Item.FindControl("rdoBed") as RadioButton;
    Literal litStatus = e.Item.FindControl("litBedStatus") as Literal;

    if (pnlCard != null)
    {
        if (intStatus == DormRegisterConst.BedStatusOccupied)
        {
            pnlCard.CssClass += " is-occupied";
        }
        else if (intStatus == DormRegisterConst.BedStatusHeld)
        {
            pnlCard.CssClass += bolMine ? " is-held is-mine" : " is-held";
        }
        else
        {
            pnlCard.CssClass += " is-empty";
        }
    }

    if (rdo != null)
    {
        rdo.Enabled = bolSelectable;
    }

    if (litStatus != null)
    {
        if (intStatus == DormRegisterConst.BedStatusOccupied)
        {
            litStatus.Text = "<span class=\"dorm-register-bed-status\"><i class=\"bi bi-person-fill\"></i> Đã có người</span>";
        }
        else if (intStatus == DormRegisterConst.BedStatusHeld)
        {
            if (bolMine)
            {
                litStatus.Text = "<span class=\"dorm-register-bed-status\"><i class=\"bi bi-pin-angle-fill\"></i> Giữ chỗ (của bạn)</span>";
            }
            else
            {
                litStatus.Text = "<span class=\"dorm-register-bed-status\"><i class=\"bi bi-hourglass-split\"></i> Giữ chỗ</span>";
            }
        }
        else
        {
            litStatus.Text = "<span class=\"dorm-register-bed-status\"><i class=\"bi bi-check-circle-fill\"></i> Trống — chọn được</span>";
        }
    }
}

