private void LoadAreaDropdown()
{
    SIM_Area obj = new SIM_Area();
    DataTable dtb = obj.GetAll();
    DataTable dtbFilter = FilterRegisterAreas(dtb);
    DormWebLookup.BindTable(ddlArea, dtbFilter, SIM_Area.C_AreaID, SIM_Area.C_AreaName);
}

private static DataTable FilterRegisterAreas(DataTable dtbSource)
{
    DataTable dtb = new DataTable();
    if (dtbSource == null)
    {
        return dtb;
    }

    dtb = dtbSource.Clone();
    int intOrder = 0;
    foreach (string strAreaId in DormRegisterConst.RegisterAreaIds)
    {
        foreach (DataRow drw in dtbSource.Rows)
        {
            if (string.Equals(drw[SIM_Area.C_AreaID].ToString(), strAreaId, StringComparison.OrdinalIgnoreCase))
            {
                dtb.ImportRow(drw);
                intOrder++;
                break;
            }
        }
    }

    return dtb;
}

