private void LoadBedList()
{
    rblBed.Items.Clear();
    pnlBedList.Visible = false;

    if (string.IsNullOrEmpty(ddlDorm.SelectedValue))
    {
        lblBedHint.Text = "Chọn phòng để xem danh sách giường.";
        return;
    }

    DataTable dtb = dataAccess.GetBedListForRegister(ddlDorm.SelectedValue, WebGlobal.StudentID);
    if (dtb == null)
    {
        MsgBox.ShowError("Không tải được danh sách giường.");
        return;
    }

    int intSelectable = 0;
    foreach (DataRow drw in dtb.Rows)
    {
        int intStatus = Convert.ToInt32(drw["BedStatus"]);
        string strName = drw["DormBedName"].ToString();
        string strLabel;
        if (intStatus == DormRegisterConst.BedStatusOccupied)
        {
            strLabel = string.Format("{0} — Đã có người", strName);
        }
        else if (intStatus == DormRegisterConst.BedStatusHeld)
        {
            if (Convert.ToInt32(drw["IsMyPendingBed"]) == 1)
            {
                strLabel = string.Format("{0} — Giữ chỗ (của bạn)", strName);
            }
            else
            {
                strLabel = string.Format("{0} — Giữ chỗ", strName);
            }
        }
        else
        {
            strLabel = string.Format("{0} — Trống", strName);
        }

        ListItem item = new ListItem(strLabel, drw["DormBedID"].ToString());
        item.Enabled = Convert.ToInt32(drw["IsSelectable"]) == 1;
        rblBed.Items.Add(item);
        if (item.Enabled)
        {
            intSelectable++;
        }
    }

    pnlBedList.Visible = dtb.Rows.Count > 0;
    lblBedHint.Text = intSelectable > 0
        ? "Chọn một giường còn trống."
        : "Phòng này không còn giường trống.";
}

