private string GetSelectedDormBedId()
{
    foreach (RepeaterItem item in rptBed.Items)
    {
        RadioButton rdo = item.FindControl("rdoBed") as RadioButton;
        HiddenField hid = item.FindControl("hidBedId") as HiddenField;
        if (rdo != null && rdo.Checked && hid != null)
        {
            return hid.Value;
        }
    }

    return string.Empty;
}

