private static void SetStepActive(HtmlGenericControl step, bool active)
{
    if (step == null)
    {
        return;
    }

    if (active)
    {
        if (step.Attributes["class"] == null || step.Attributes["class"].IndexOf("is-active") < 0)
        {
            step.Attributes["class"] = (step.Attributes["class"] ?? "dorm-register-step") + " is-active";
        }
    }
    else
    {
        string strClass = step.Attributes["class"] ?? "dorm-register-step";
        step.Attributes["class"] = strClass.Replace(" is-active", "").Replace("is-active", "").Trim();
        if (step.Attributes["class"].Length == 0)
        {
            step.Attributes["class"] = "dorm-register-step";
        }
    }
}

