    dtbBedsInArea = BuildBedTableForArea(ddlArea.SelectedValue);
    BindBedRepeater();
}

private DataTable BuildBedTableForArea(string areaId)
{
    DataTable dtbResult = null;
    DataTable dtbDorms = dataAccess.GetDormListForRegister(areaId, WebGlobal.StudentID);
    if (dtbDorms == null || dtbDorms.Rows.Count == 0)
    {
        return dtbResult;
    }

    foreach (DataRow drwDorm in dtbDorms.Rows)
    {
        string strDormId = drwDorm[SIM_Dorm.C_DormID].ToString();
        DataTable dtbBeds = dataAccess.GetBedListForRegister(strDormId, WebGlobal.StudentID);
        if (dtbBeds == null || dtbBeds.Rows.Count == 0)
        {
            continue;
        }

        if (dtbResult == null)
        {
            dtbResult = dtbBeds.Clone();
        }

        foreach (DataRow drwBed in dtbBeds.Rows)
        {
            dtbResult.ImportRow(drwBed);
        }
    }

    return dtbResult;
}

private void BindBedRepeater()
{
    DataTable dtb = GetFilteredBedTable();
    rptBed.DataSource = dtb;
    rptBed.DataBind();

    if (dtb == null || dtb.Rows.Count == 0)
    {
        pnlBedList.Visible = false;
        lblBedHint.Text = "Khu này chưa có phòng/giường hiển thị.";
        return;
    }

    int intSelectable = 0;
    foreach (DataRow drw in dtb.Rows)
    {
        if (Convert.ToInt32(drw["IsSelectable"]) == 1)
        {
            intSelectable++;
        }
    }

    pnlBedList.Visible = true;
    if (string.IsNullOrEmpty(ddlDorm.SelectedValue))
    {
        lblBedHint.Text = intSelectable > 0
            ? "Danh sách giường trong khu (có thể lọc theo phòng). Bấm thẻ xanh để chọn — chỉ một giường."
            : "Khu này không còn giường trống.";
    }
    else
    {
        lblBedHint.Text = intSelectable > 0
            ? "Chọn một giường trống (thẻ xanh)."
            : "Phòng này không còn giường trống.";
    }
}

private DataTable GetFilteredBedTable()
{
    if (dtbBedsInArea == null)
    {
        return null;
    }

    if (string.IsNullOrEmpty(ddlDorm.SelectedValue))
    {
        return dtbBedsInArea;
    }

    DataTable dtbFilter = dtbBedsInArea.Clone();
    foreach (DataRow drw in dtbBedsInArea.Rows)
    {
        if (drw[SIM_Dorm.C_DormID].ToString() == ddlDorm.SelectedValue)
        {
            dtbFilter.ImportRow(drw);
        }
    }

    return dtbFilter;
}

private void ClearBedList()
{
    dtbBedsInArea = null;
    hidSelectedDormBedID.Value = string.Empty;
    rptBed.DataSource = null;
    rptBed.DataBind();
    pnlBedList.Visible = false;
    lblBedHint.Text = "Chọn khu để xem phòng và giường.";
}

