private static bool IsEmptySelectableBed(DataRow drw)
{
    if (drw == null)
    {
        return false;
    }

    return Convert.ToInt32(drw["BedStatus"]) == DormRegisterConst.BedStatusEmpty
        && Convert.ToInt32(drw["IsSelectable"]) == 1;
}

private DataTable GetFilteredBedTable()
{
    if (dtbBedsInArea == null)
    {
        return null;
    }

    DataTable dtbFilter = dtbBedsInArea.Clone();
    foreach (DataRow drw in dtbBedsInArea.Rows)
    {
        if (!IsEmptySelectableBed(drw))
        {
            continue;
        }

        if (!string.IsNullOrEmpty(ddlDorm.SelectedValue)
            && drw[SIM_Dorm.C_DormID].ToString() != ddlDorm.SelectedValue)
        {
            continue;
        }

        dtbFilter.ImportRow(drw);
    }

    if (dtbFilter.Rows.Count == 0)
    {
        return dtbFilter;
    }

    DataView dv = dtbFilter.DefaultView;
    dv.Sort = "DormName, DormBedName";
    return dv.ToTable();
}

