private DataTable BuildRoomSummaryTable(DataTable dtbBeds)
{
    DataTable dtbRooms = new DataTable();
    dtbRooms.Columns.Add("DormID", typeof(string));
    dtbRooms.Columns.Add("DormName", typeof(string));
    dtbRooms.Columns.Add("BedCount", typeof(int));
    dtbRooms.Columns.Add("ToneIndex", typeof(int));

    if (dtbBeds == null || dtbBeds.Rows.Count == 0)
    {
        return dtbRooms;
    }

    int intTone = 0;
    string strLastDormId = string.Empty;
    foreach (DataRow drw in dtbBeds.Rows)
    {
        string strDormId = drw[SIM_Dorm.C_DormID].ToString();
        if (strDormId == strLastDormId)
        {
            continue;
        }

        strLastDormId = strDormId;
        int intCount = 0;
        foreach (DataRow drwCount in dtbBeds.Rows)
        {
            if (drwCount[SIM_Dorm.C_DormID].ToString() == strDormId)
            {
                intCount++;
            }
        }

        DataRow drwNew = dtbRooms.NewRow();
        drwNew["DormID"] = strDormId;
        drwNew["DormName"] = drw["DormName"];
        drwNew["BedCount"] = intCount;
        drwNew["ToneIndex"] = intTone;
        dtbRooms.Rows.Add(drwNew);
        intTone++;
    }

    return dtbRooms;
}

