using System;
using System.Data;
using System.Globalization;
using System.Web.UI;
using System.Web.UI.WebControls;
using DCore;
using WebGlobal;

namespace InformationWeb.Controls.Dorm.DormRegister
{
    public partial class Approve : DCore.ControlBase
    {
        private const int HistoryDays = 90;

        private DormRegisterDataAccess dataAccess = new DormRegisterDataAccess();

        private bool bolCanApprove;

        protected void Page_Load(object sender, EventArgs e)
        {
            if (Session[Globals.USER] == null)
            {
                MsgBox.ShowError("Bạn chưa đăng nhập hệ thống!");
                return;
            }

            if (!WebGlobal.HasPermission(DormRegisterConst.PERMISSION_APPROVE)
                && !WebGlobal.HasPermission(DormRegisterConst.PERMISSION_VIEW))
            {
                MsgBox.ShowError("Bạn không có quyền duyệt đăng ký ký túc xá.");
                return;
            }

            bolCanApprove = WebGlobal.HasPermission(DormRegisterConst.PERMISSION_APPROVE);

            if (!IsPostBack)
            {
                hidListStatus.Value = DormRegisterConst.StatusPending.ToString();
                LoadRequestGrid();
                UpdateTabHighlight();
            }
        }

        protected void btnTabPending_Click(object sender, EventArgs e)
        {
            SwitchListTab(DormRegisterConst.StatusPending);
        }

        protected void btnTabApproved_Click(object sender, EventArgs e)
        {
            SwitchListTab(DormRegisterConst.StatusApproved);
        }

        protected void btnTabRejected_Click(object sender, EventArgs e)
        {
            SwitchListTab(DormRegisterConst.StatusRejected);
        }

        protected void btnTabCancelled_Click(object sender, EventArgs e)
        {
            SwitchListTab(DormRegisterConst.StatusCancelled);
        }

        protected void grdPending_SelectedIndexChanged(object sender, EventArgs e)
        {
            if (grdPending.SelectedDataKey == null)
            {
                return;
            }

            long lngId = Convert.ToInt64(grdPending.SelectedDataKey.Value);
            hidSelectedRequestID.Value = lngId.ToString();
            LoadDetail(lngId);
            ApplyGridSelectedRowStyle();
            udpAll.Update();
        }

        protected void grdPending_RowDataBound(object sender, GridViewRowEventArgs e)
        {
            if (e.Row.RowType != DataControlRowType.DataRow)
            {
                return;
            }

            if (e.Row.RowIndex == grdPending.SelectedIndex)
            {
                e.Row.CssClass = "dorm-register-row-selected";
            }

            FormatGridDateCell(e.Row, 6, "RegisterDate");
            FormatGridDateCell(e.Row, 7, "ProcessDate");
        }

        protected void btnApprove_Click(object sender, EventArgs e)
        {
            if (!bolCanApprove)
            {
                MsgBox.ShowWarning("Bạn không có quyền duyệt.");
                return;
            }

            long lngId;
            if (!long.TryParse(hidSelectedRequestID.Value, out lngId) || lngId <= 0)
            {
                MsgBox.ShowWarning("Vui lòng chọn một đơn trong danh sách.");
                return;
            }

            string strUser = User != null ? User.UserName : "web";
            if (!dataAccess.Approve(lngId, strUser))
            {
                string strErr = GetDalErrorMessage("Duyệt thất bại.");
                MsgBox.ShowError(strErr);
                return;
            }

            MsgBox.ShowInfo("Đã duyệt đăng ký và ghi nhận nội trú.");
            ClearDetailSelection();
            LoadRequestGrid();
            udpAll.Update();
        }

        protected void btnReject_Click(object sender, EventArgs e)
        {
            if (!bolCanApprove)
            {
                MsgBox.ShowWarning("Bạn không có quyền từ chối.");
                return;
            }

            long lngId;
            if (!long.TryParse(hidSelectedRequestID.Value, out lngId) || lngId <= 0)
            {
                MsgBox.ShowWarning("Vui lòng chọn một đơn trong danh sách.");
                return;
            }

            if (string.IsNullOrWhiteSpace(txtRejectReason.Text))
            {
                MsgBox.ShowWarning("Vui lòng nhập lý do từ chối.");
                return;
            }

            string strUser = User != null ? User.UserName : "web";
            if (!dataAccess.Reject(lngId, txtRejectReason.Text.Trim(), strUser))
            {
                string strErr = GetDalErrorMessage("Từ chối thất bại.");
                MsgBox.ShowError(strErr);
                return;
            }

            MsgBox.ShowInfo("Đã từ chối đăng ký.");
            ClearDetailSelection();
            LoadRequestGrid();
            udpAll.Update();
        }

        private void SwitchListTab(byte status)
        {
            hidListStatus.Value = status.ToString();
            ClearDetailSelection();
            LoadRequestGrid();
            UpdateTabHighlight();
            udpAll.Update();
        }

        private void LoadRequestGrid()
        {
            byte bytStatus = GetCurrentListStatus();
            DataTable dtb;
            if (bytStatus == DormRegisterConst.StatusPending)
            {
                dtb = dataAccess.SearchForManager(bytStatus, null, null);
                if (dtb == null)
                {
                    dtb = dataAccess.GetPendingList();
                }
            }
            else
            {
                DateTime dtmTo = DateTime.Today;
                DateTime dtmFrom = dtmTo.AddDays(-HistoryDays);
                dtb = dataAccess.SearchForManager(bytStatus, dtmFrom, dtmTo);
            }

            if (dtb == null)
            {
                MsgBox.ShowError("Không tải được danh sách phiếu.");
                return;
            }

            pnlHistoryHint.Visible = bytStatus != DormRegisterConst.StatusPending;
            SetGridColumnsForStatus(bytStatus);
            grdPending.SelectedIndex = -1;
            grdPending.DataSource = dtb;
            grdPending.DataBind();
        }

        private byte GetCurrentListStatus()
        {
            byte bytStatus;
            if (!byte.TryParse(hidListStatus.Value, out bytStatus))
            {
                bytStatus = DormRegisterConst.StatusPending;
            }

            return bytStatus;
        }

        private void SetGridColumnsForStatus(byte status)
        {
            bool bolPending = status == DormRegisterConst.StatusPending;
            grdPending.Columns[7].Visible = !bolPending;
            grdPending.Columns[8].Visible = !bolPending;
            grdPending.Columns[9].Visible = !bolPending;
        }

        private void LoadDetail(long registerRequestId)
        {
            DataTable dtb = dataAccess.GetRequestDetail(registerRequestId);
            if (dtb == null || dtb.Rows.Count == 0)
            {
                MsgBox.ShowWarning("Không tìm thấy chi tiết đơn.");
                SetDetailVisible(false);
                return;
            }

            DataRow drw = dtb.Rows[0];
            byte bytStatus = Convert.ToByte(drw["Status"]);
            bool bolPending = bytStatus == DormRegisterConst.StatusPending;

            litFullname.Text = drw["Fullname"].ToString();
            litStudentCode.Text = drw["StudentCode"].ToString();
            litArea.Text = drw["AreaName"].ToString();
            litDorm.Text = drw["DormName"].ToString();
            litBed.Text = drw["DormBedName"].ToString();
            litRegisterDate.Text = FormatDate(drw["RegisterDate"]);

            pnlStatusBadge.Visible = !bolPending;
            litStatusName.Text = drw["StatusName"].ToString();
            ApplyStatusBadgeCss(bytStatus);

            pnlProcessInfo.Visible = !bolPending;
            pnlRejectInput.Visible = bolPending;
            btnApprove.Visible = bolCanApprove && bolPending;
            btnReject.Visible = bolCanApprove && bolPending;

            if (!bolPending)
            {
                litProcessDate.Text = FormatDateTime(drw["ProcessDate"]);
                litProcessUser.Text = drw["ProcessUser"] != DBNull.Value ? drw["ProcessUser"].ToString() : string.Empty;
                bool bolRejected = bytStatus == DormRegisterConst.StatusRejected;
                pnlRejectReasonDisplay.Visible = bolRejected;
                if (bolRejected && drw["RejectReason"] != DBNull.Value)
                {
                    litRejectReason.Text = drw["RejectReason"].ToString();
                }
                else
                {
                    litRejectReason.Text = string.Empty;
                }
            }
            else
            {
                txtRejectReason.Text = string.Empty;
            }

            SetDetailVisible(true);
        }

        private void ApplyStatusBadgeCss(byte status)
        {
            string strClass = "dorm-register-approve-status-badge";
            if (status == DormRegisterConst.StatusApproved)
            {
                strClass += " is-approved";
            }
            else if (status == DormRegisterConst.StatusRejected)
            {
                strClass += " is-rejected";
            }
            else if (status == DormRegisterConst.StatusCancelled)
            {
                strClass += " is-cancelled";
            }

            pnlStatusBadge.CssClass = "mb-3 " + strClass.Replace(" dorm-register-approve-status-badge", string.Empty);
            pnlStatusBadge.CssClass = "mb-3";
            // badge class on inner span via panel - set on Panel wrapper
            pnlStatusBadge.CssClass = "mb-3 dorm-register-approve-status-wrap";
        }

        private void UpdateTabHighlight()
        {
            byte bytStatus = GetCurrentListStatus();
            SetTabActive(btnTabPending, bytStatus == DormRegisterConst.StatusPending);
            SetTabActive(btnTabApproved, bytStatus == DormRegisterConst.StatusApproved);
            SetTabActive(btnTabRejected, bytStatus == DormRegisterConst.StatusRejected);
            SetTabActive(btnTabCancelled, bytStatus == DormRegisterConst.StatusCancelled);
        }

        private static void SetTabActive(LinkButton tab, bool active)
        {
            if (tab == null)
            {
                return;
            }

            string strClass = "nav-link dorm-register-approve-tab";
            if (active)
            {
                strClass += " active";
            }

            tab.CssClass = strClass;
        }

        private void ClearDetailSelection()
        {
            SetDetailVisible(false);
            hidSelectedRequestID.Value = string.Empty;
            txtRejectReason.Text = string.Empty;
            grdPending.SelectedIndex = -1;
        }

        private void SetDetailVisible(bool showDetail)
        {
            pnlDetail.Visible = showDetail;
            pnlDetailPlaceholder.Visible = !showDetail;
        }

        private void ApplyGridSelectedRowStyle()
        {
            foreach (GridViewRow row in grdPending.Rows)
            {
                if (row.RowType != DataControlRowType.DataRow)
                {
                    continue;
                }

                if (row.RowIndex == grdPending.SelectedIndex)
                {
                    row.CssClass = "dorm-register-row-selected";
                }
            }
        }

        private void FormatGridDateCell(GridViewRow row, int cellIndex, string fieldName)
        {
            if (row.Cells.Count <= cellIndex)
            {
                return;
            }

            object objDate = DataBinder.Eval(row.DataItem, fieldName);
            if (objDate != null && objDate != DBNull.Value)
            {
                DateTime dtm = Convert.ToDateTime(objDate);
                if (fieldName == "ProcessDate")
                {
                    row.Cells[cellIndex].Text = dtm.ToString("dd/MM/yyyy HH:mm", CultureInfo.InvariantCulture);
                }
                else
                {
                    row.Cells[cellIndex].Text = dtm.ToString("dd/MM/yyyy", CultureInfo.InvariantCulture);
                }
            }
            else if (fieldName == "ProcessDate")
            {
                row.Cells[cellIndex].Text = string.Empty;
            }
        }

        private string GetDalErrorMessage(string defaultMessage)
        {
            if (dataAccess.ErrorException != null)
            {
                return dataAccess.ErrorException.Message;
            }

            return defaultMessage;
        }

        private static string FormatDate(object value)
        {
            if (value == null || value == DBNull.Value)
            {
                return string.Empty;
            }

            DateTime dtm = Convert.ToDateTime(value);
            return dtm.ToString("dd/MM/yyyy", CultureInfo.InvariantCulture);
        }

        private static string FormatDateTime(object value)
        {
            if (value == null || value == DBNull.Value)
            {
                return string.Empty;
            }

            DateTime dtm = Convert.ToDateTime(value);
            return dtm.ToString("dd/MM/yyyy HH:mm", CultureInfo.InvariantCulture);
        }
    }
}

